xql_query:
// ============================================================
// Rule: FTG_Local User Account Created
// Vendor: Fortigate
// Objective:
// Detect activity associated with FTG_Local User Account Created.
// Severity: SEV_040_HIGH
// Category: OTHER
// ============================================================
// SANITIZED: Environment-specific values replaced with generic placeholders.
// MITRE ATT&CK:
// Tactic: TA0003 - Persistence
// Technique: T1136 - Create Account
// Technique: T1136.001 - Create Account: Local Account

// Fonte de dados: logs brutos do Fortinet FortiGate
dataset = fortinet_fortigate_raw  

// Filtra apenas mensagens que contenham o termo "accprofile"
// Normalmente relacionado a perfis de acesso/controle no FortiGate
| filter msg contains "accprofile"  

// Criação de campos derivados para facilitar a análise dos resultados
| alter
    timestamp = _time,                    // Momento em que o evento ocorreu
    src_ip = src,                         // Endereço IP de origem
    dst_ip = dst,                         // Endereço IP de destino
    log_message = msg,                     // Mensagem bruta do log
    action_taken = act,                   // Ação registrada pelo dispositivo
    application = app,                    // Aplicação associada ao evento
    request_origin = dhost,               // Host de destino ou origem da requisição
    user = duser,                         // Usuário envolvido (quando aplicável)
    device_name = _reporting_device_name  // Nome do dispositivo FortiGate que gerou o log

// Seleção dos campos principais para exibição
| fields timestamp, device_name, src_ip, dst_ip, log_message, application, action_taken, request_origin, user
